import socket, struct

def query(name, qtype=1):
    qname = b''.join(bytes([len(p)]) + p.encode() for p in name.split('.')) + b'\x00'
    header = struct.pack('>HHHHHH', 0x9999, 0x0100, 1, 0, 0, 0)
    q = header + qname + struct.pack('>HH', qtype, 1)
    s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM); s.settimeout(1.0)
    try:
        s.sendto(q, ('127.0.0.11', 53)); data,_ = s.recvfrom(2048)
        return data
    except Exception:
        return None
    finally: s.close()

def parse(data):
    if not data or len(data)<12: return []
    an = struct.unpack('>H', data[6:8])[0]; ns = struct.unpack('>H', data[8:10])[0]; ar = struct.unpack('>H', data[10:12])[0]
    off=12
    while off<len(data):
        l=data[off]
        if l==0: off+=1; break
        off += l+1
    off += 4
    res=[]
    for _ in range(an+ns+ar):
        try:
            if data[off]&0xC0==0xC0: off+=2
            else:
                while data[off]!=0: off+=1+data[off]
                off+=1
            rtype,rclass,ttl,rdlen=struct.unpack('>HHIH', data[off:off+10]); off+=10
            if rtype==1 and rdlen==4:
                res.append(('A', socket.inet_ntoa(data[off:off+4])))
            elif rtype==16 and rdlen>0:
                # TXT: length-prefixed strings
                idx=off; parts=[]
                while idx<off+rdlen:
                    l=data[idx]; idx+=1; parts.append(data[idx:idx+l].decode(errors='replace')); idx+=l
                res.append(('TXT', parts))
            elif rtype==5:
                res.append(('CNAME', '?'))
            off+=rdlen
        except Exception as e:
            break
    return res

